import base64, json
from pathlib import Path
bundle = json.loads(base64.b64decode("").decode())
for rel, content in bundle.items():
    p = Path("/code") / rel
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(content)
    print("wrote", rel)
print("ALL_FILE_PATCHES_OK", len(bundle), "mobile-gql-v16")
